CREATE TABLE students (id INTEGER PRIMARY KEY, name TEXT);
CREATE TABLE scores (sid INTEGER, course TEXT, score INTEGER);
INSERT INTO students VALUES (1, '小明'), (2, '小红'), (3, '小刚'), (4, '小美');
INSERT INTO scores VALUES (1, '数据库', 88), (2, '数据库', 92), (2, '操作系统', 95), (3, '数据库', 70);
SELECT s.name, SUM(c.score) AS total
FROM students s
LEFT JOIN scores c ON s.id = c.sid
GROUP BY s.id, s.name
ORDER BY total DESC;
